package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.impl.rocksdb.ReplicatedRangeStore;
import java.nio.ByteBuffer;
import java.util.*;

/** Actual current owner/native configuration evidence. Serialized requests convey no membership authority. */
public final class RatisRelocationOwnerRpc {
    public static final int KIND=104,MAX_REQUEST_BYTES=ScopedTransactionRpc.HEADER_BYTES+72+TopologyChange.MAX_DEFINITION_BYTES;
    public static final int MAX_REPLY_BYTES=ScopedTransactionRpc.HEADER_BYTES+152+65536;
    public enum Expected { SOURCE, TARGET, CAUGHT_UP, IMAGE }
    public record Request(TopologyChange.Definition definition,UUID replica,Expected expected,ApplyPosition requiredCut,byte[] imageHash){
        public Request { Objects.requireNonNull(definition);Objects.requireNonNull(expected);if(definition.kind()!=TopologyChange.Kind.RELOCATE || expected==Expected.CAUGHT_UP && (replica==null || requiredCut==null) || requiredCut!=null && requiredCut.term()<1 || expected==Expected.IMAGE && (replica==null || requiredCut==null || imageHash==null) || imageHash!=null && imageHash.length!=32)throw new IllegalArgumentException("Invalid relocation owner request");imageHash=imageHash==null?null:imageHash.clone(); }
        @Override public byte[] imageHash(){return imageHash==null?null:imageHash.clone();}
        public byte[] digest(){return OperatorUpload.sha256(request(this));}
    }
    public record Evidence(byte[] requestDigest,TopologyChange.Owner owner,ApplyPosition completedCut,ReplicatedRangeStore.Configuration configuration,byte[] learnerDigest,boolean imageInstalled,boolean caughtUp){
        public Evidence { if(requestDigest==null || requestDigest.length!=32 || learnerDigest!=null && learnerDigest.length!=32)throw new IllegalArgumentException("Invalid relocation evidence digest");Objects.requireNonNull(owner);Objects.requireNonNull(completedCut);Objects.requireNonNull(configuration);requestDigest=requestDigest.clone();learnerDigest=learnerDigest==null?null:learnerDigest.clone();if(completedCut.term()<1 || configuration.term()>completedCut.term() || configuration.index()>completedCut.index() || configuration.index()==completedCut.index() && configuration.term()!=completedCut.term() || caughtUp && !imageInstalled)throw new IllegalArgumentException("Invalid relocation native cut"); }
        @Override public byte[] requestDigest(){return requestDigest.clone();}@Override public byte[] learnerDigest(){return learnerDigest==null?null:learnerDigest.clone();}
        public void require(Request request){if(!Arrays.equals(requestDigest,request.digest()))throw new IllegalArgumentException("Crossed relocation request");var range=request.expected()==Expected.SOURCE?request.definition().parents().getFirst():request.definition().targets().getFirst();if(!range.replicas().stream().map(TopologyChange.Owner::of).toList().contains(owner) || request.replica()!=null && !request.replica().equals(owner.replicaId()) || request.requiredCut()!=null && caughtUp && !covers(completedCut,request.requiredCut()))throw new IllegalArgumentException("Crossed relocation owner/catch-up cut");}
        public TopologyChange.RelocationProof proof(UUID group,ApplyPosition required){return new TopologyChange.RelocationProof(group,owner,new ApplyPosition(configuration.term(),configuration.index()),completedCut,required,OperatorUpload.sha256(configuration.data()));}
    }
    private RatisRelocationOwnerRpc(){}
    static boolean covers(ApplyPosition cut,ApplyPosition expected){return cut.term()>=expected.term() && cut.index()>=expected.index() && (cut.index()!=expected.index() || cut.term()==expected.term());}
    public static byte[] request(Request request){byte[] definition=request.definition().encode();var out=ByteBuffer.allocate(72+definition.length);ScopedTransactionRpc.putBlob(out,definition);out.put((byte)(request.replica()==null?0:1));ScopedTransactionRpc.uuid(out,request.replica()==null?new UUID(0,0):request.replica());out.put((byte)request.expected().ordinal());out.put((byte)(request.requiredCut()==null?0:1));out.putLong(request.requiredCut()==null?0:request.requiredCut().term()).putLong(request.requiredCut()==null?0:request.requiredCut().index());out.put((byte)(request.imageHash()==null?0:1));out.put(request.imageHash()==null?new byte[32]:request.imageHash());return ScopedTransactionRpc.frame(KIND,out.array());}
    public static Request decode(byte[] bytes){var packet=ScopedTransactionRpc.parse(bytes,MAX_REQUEST_BYTES);if(packet.kind()!=KIND)throw new IllegalArgumentException("Wrong relocation owner kind");var in=ByteBuffer.wrap(packet.body());var definition=TopologyChange.Definition.decode(ScopedTransactionRpc.blob(in,TopologyChange.MAX_DEFINITION_BYTES,false));if(in.remaining()!=68)throw new IllegalArgumentException("Invalid relocation owner tail");int present=in.get()&255;var replica=ScopedTransactionRpc.uuid(in);int expected=in.get()&255;int cutPresent=in.get()&255;long term=in.getLong(),index=in.getLong();if(expected>=Expected.values().length || present>1 || cutPresent>1 || present==0 && !replica.equals(new UUID(0,0)) || cutPresent==0 && (term!=0 || index!=0))throw new IllegalArgumentException("Invalid relocation owner action");int hashPresent=in.get()&255;byte[] hash=new byte[32];in.get(hash);if(hashPresent>1 || hashPresent==0 && !Arrays.equals(hash,new byte[32]))throw new IllegalArgumentException("Invalid image hash framing");return new Request(definition,present==0?null:replica,Expected.values()[expected],cutPresent==0?null:new ApplyPosition(term,index),hashPresent==0?null:hash);}
    public static byte[] reply(Evidence evidence){byte[] cfg=evidence.configuration().data();var out=ByteBuffer.allocate(152+cfg.length);out.put(evidence.requestDigest());ScopedTransactionRpc.uuid(out,evidence.owner().replicaId());out.put((byte)evidence.owner().role().ordinal()).put(evidence.owner().identityDigest());out.putLong(evidence.completedCut().term()).putLong(evidence.completedCut().index()).putLong(evidence.configuration().term()).putLong(evidence.configuration().index());ScopedTransactionRpc.putBlob(out,cfg);out.put((byte)(evidence.learnerDigest()==null?0:1));out.put(evidence.learnerDigest()==null?new byte[32]:evidence.learnerDigest());out.put((byte)(evidence.imageInstalled()?1:0)).put((byte)(evidence.caughtUp()?1:0));return ScopedTransactionRpc.frame(KIND,out.array());}
    public static Evidence decodeReply(byte[] bytes,Request request){var packet=ScopedTransactionRpc.parse(bytes,MAX_REPLY_BYTES);if(packet.kind()!=KIND || packet.body().length<152)throw new IllegalArgumentException("Invalid relocation reply");var in=ByteBuffer.wrap(packet.body());byte[] digest=new byte[32];in.get(digest);var replica=ScopedTransactionRpc.uuid(in);int role=in.get()&255;if(role>=ReplicaDescriptor.Role.values().length)throw new IllegalArgumentException("Invalid owner role");byte[] identity=new byte[32];in.get(identity);var cut=new ApplyPosition(in.getLong(),in.getLong());long term=in.getLong(),index=in.getLong();var cfg=new ReplicatedRangeStore.Configuration(term,index,ScopedTransactionRpc.blob(in,65536,false));if(in.remaining()!=35)throw new IllegalArgumentException("Invalid relocation flags");int present=in.get()&255;byte[] learner=new byte[32];in.get(learner);int installed=in.get()&255,caught=in.get()&255;if(present>1 || installed>1 || caught>1 || present==0 && !Arrays.equals(learner,new byte[32]))throw new IllegalArgumentException("Invalid relocation evidence flags");var evidence=new Evidence(digest,new TopologyChange.Owner(replica,ReplicaDescriptor.Role.values()[role],identity),cut,cfg,present==0?null:learner,installed==1,caught==1);evidence.require(request);return evidence;}
}
